{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Map node to index for DSU
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)

    # Build edges: canonical order (node1 < node2 lexicographically)
    edges = []
    for u, v, d in distances:
        # Make sure both nodes are known
        if u not in node_to_idx or v not in node_to_idx:
            raise ValueError(f"Unknown node in distance: {u} or {v}")
        # canonicalize
        if u > v:
            u, v = v, u
        # mutual reachability
        w = max(core[u], core[v], d)
        edges.append((w, u, v))

    # Sort by weight, then by u, then by v (tie-breaking)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # DSU
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    edges_needed = n - 1

    for w, u, v in edges:
        if union(node_to_idx[u], node_to_idx[v]):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == edges_needed:
                break

    if len(mst_edges) != edges_needed:
        raise ValueError("Graph is disconnected, cannot form MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
